import { useCallback, useEffect, useState } from 'react'
import { seedBoard, newCard, nextId } from '../data/board.js'

const STORAGE_KEY = 'kanvy.board'

function loadInitialBoard() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (raw) return JSON.parse(raw)
  } catch {
    // ignore corrupt storage, fall back to seed
  }
  return seedBoard
}

export function useBoard() {
  const [board, setBoard] = useState(loadInitialBoard)

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(board))
  }, [board])

  const addCard = useCallback((type, opts) => {
    setBoard((b) => ({ ...b, cards: [...b.cards, newCard(type, opts)] }))
  }, [])

  const updateCard = useCallback((id, patch) => {
    setBoard((b) => ({
      ...b,
      cards: b.cards.map((c) => (c.id === id ? { ...c, ...patch } : c)),
    }))
  }, [])

  const moveCard = useCallback((id, x, y) => {
    setBoard((b) => ({
      ...b,
      cards: b.cards.map((c) => (c.id === id ? { ...c, x, y } : c)),
    }))
  }, [])

  const removeCard = useCallback((id) => {
    setBoard((b) => ({ ...b, cards: b.cards.filter((c) => c.id !== id) }))
  }, [])

  const addTask = useCallback((cardId, text) => {
    setBoard((b) => ({
      ...b,
      cards: b.cards.map((c) =>
        c.id === cardId
          ? { ...c, tasks: [...c.tasks, { id: nextId('t'), text, done: false }] }
          : c,
      ),
    }))
  }, [])

  const toggleTask = useCallback((cardId, taskId) => {
    setBoard((b) => ({
      ...b,
      cards: b.cards.map((c) =>
        c.id === cardId
          ? {
              ...c,
              tasks: c.tasks.map((t) => (t.id === taskId ? { ...t, done: !t.done } : t)),
            }
          : c,
      ),
    }))
  }, [])

  const removeTask = useCallback((cardId, taskId) => {
    setBoard((b) => ({
      ...b,
      cards: b.cards.map((c) =>
        c.id === cardId ? { ...c, tasks: c.tasks.filter((t) => t.id !== taskId) } : c,
      ),
    }))
  }, [])

  const resetBoard = useCallback(() => {
    setBoard(seedBoard)
  }, [])

  return {
    board,
    addCard,
    updateCard,
    moveCard,
    removeCard,
    addTask,
    toggleTask,
    removeTask,
    resetBoard,
  }
}

