:root {
  color-scheme: light;
  --paper: #f4f1ea;
  --ink: #1a1a1a;
  --line: #1a1a1a;
  font-family: 'Courier New', 'Space Mono', monospace;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background: var(--paper);
  color: var(--ink);
  background-image: radial-gradient(#00000014 1px, transparent 1px);
  background-size: 22px 22px;
}

.app {
  height: 100%;
  display: flex;
  flex-direction: column;
}

/* ---------- toolbar ---------- */

.toolbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: var(--paper);
  border-bottom: 3px solid var(--line);
}

.toolbar__brand {
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: 0.02em;
  margin-right: 8px;
}

.toolbar__btn {
  font-family: inherit;
  font-size: 0.85rem;
  background: #fff;
  border: 2px solid var(--line);
  padding: 6px 12px;
  cursor: pointer;
  box-shadow: 3px 3px 0 var(--line);
}

.toolbar__btn:hover {
  transform: translate(1px, 1px);
  box-shadow: 2px 2px 0 var(--line);
}

.toolbar__btn--ghost {
  margin-left: auto;
  background: transparent;
}

.toolbar__colors {
  display: flex;
  gap: 6px;
  padding: 0 6px;
  border-left: 2px solid var(--line);
  border-right: 2px solid var(--line);
  margin: 0 4px;
}

.toolbar__swatch {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid var(--line);
  cursor: pointer;
  padding: 0;
}

.toolbar__swatch--active {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}

/* ---------- board ---------- */

.board {
  position: relative;
  flex: 1 1 auto;
  overflow: auto;
  min-height: 0;
}

/* ---------- card ---------- */

.card {
  position: absolute;
  background: #fff;
  border: 3px solid var(--line);
  border-radius: 2px;
  box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.85);
  padding: 0;
  cursor: grab;
  user-select: none;
}

.card--dragging {
  cursor: grabbing;
  box-shadow: 6px 6px 0 rgba(0, 0, 0, 0.85);
  z-index: 10;
}

.card__bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border-bottom: 2px solid var(--line);
}

.card__dot {
  flex: 0 0 auto;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid var(--line);
}

.card__title {
  flex: 1 1 auto;
  min-width: 0;
  font-family: inherit;
  font-weight: 700;
  font-size: 0.9rem;
  border: none;
  background: transparent;
  cursor: text;
}

.card__title:focus {
  outline: none;
  text-decoration: underline;
}

.card__close {
  flex: 0 0 auto;
  border: none;
  background: transparent;
  font-size: 1rem;
  line-height: 1;
  cursor: pointer;
  padding: 2px 4px;
}

.card__close:hover {
  color: #d33;
}

.card__content {
  display: block;
  width: 100%;
  min-height: 64px;
  border: none;
  resize: vertical;
  font-family: inherit;
  font-size: 0.85rem;
  padding: 8px;
  background: transparent;
  cursor: text;
}

.card__content:focus {
  outline: none;
}

.card__tasks {
  padding: 6px 8px 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.task-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.85rem;
  cursor: default;
  padding: 2px 0;
}

.task-row__text {
  flex: 1 1 auto;
}

.task-row__text--done {
  text-decoration: line-through;
  opacity: 0.5;
}

.task-row__remove {
  border: none;
  background: transparent;
  cursor: pointer;
  opacity: 0;
  padding: 0 4px;
}

.task-row:hover .task-row__remove {
  opacity: 0.6;
}

.task-row__remove:hover {
  opacity: 1;
  color: #d33;
}

.task-add {
  margin-top: 4px;
}

.task-add input {
  width: 100%;
  border: none;
  border-top: 1px dashed #999;
  font-family: inherit;
  font-size: 0.85rem;
  padding: 6px 0 2px;
  background: transparent;
  cursor: text;
}

.task-add input:focus {
  outline: none;
}

