}

.card__dot {
  flex: 0 0 auto;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid var(--line);
}

.card__title {
  flex: 1 1 auto;
  min-width: 0;
  font-family: inherit;
  font-weight: 700;
  font-size: 0.9rem;
  border: none;
  background: transparent;
  cursor: text;
}

.card__title:focus {
  outline: none;
  text-decoration: underline;
}

.card__close {
  flex: 0 0 auto;
  border: none;
  background: transparent;
  font-size: 1rem;
  line-height: 1;
