.task-row__text {
  flex: 1 1 auto;
}

.task-row__text--done {
  text-decoration: line-through;
  opacity: 0.5;
}

.task-row__remove {
  border: none;
  background: transparent;
  cursor: pointer;
  opacity: 0;
  padding: 0 4px;
