  width: 100%;
  border: none;
  border-top: 1px dashed #999;
  font-family: inherit;
  font-size: 0.85rem;
  padding: 6px 0 2px;
  background: transparent;
  cursor: text;
}

.task-add input:focus {
  outline: none;
}

